    /// The strokes as chains of cubic Bézier segments (a Catmull-Rom curve through the points).
    static let strokes: [Stroke] = points.map { curve(through: $0) }

    private static func curve(through p: [CGPoint]) -> Stroke {
        guard p.count > 1 else { return [] }
        return (0..<(p.count - 1)).map { i in
            let p0 = p[max(i - 1, 0)], p1 = p[i], p2 = p[i + 1], p3 = p[min(i + 2, p.count - 1)]
            return Segment(start: p1,
                           control1: CGPoint(x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6),
                           control2: CGPoint(x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6),
                           end: p2)
        }
    }

    // MARK: Measurements (used to fit the writing and to animate the pen at a constant speed)

    /// The box around the strokes including half the pen width (y up).
    static let bounds: CGRect = {
        var minX = CGFloat.infinity, maxX = -CGFloat.infinity, minY = CGFloat.infinity, maxY = -CGFloat.infinity
        for stroke in points { for p in stroke {
            minX = min(minX, p.x); maxX = max(maxX, p.x); minY = min(minY, p.y); maxY = max(maxY, p.y)
        } }
        return CGRect(x: minX, y: minY, width: maxX - minX, height: maxY - minY).insetBy(dx: -penWidth / 2, dy: -penWidth / 2)
    }()

    /// Approximate length of each stroke.
    static let strokeLengths: [CGFloat] = strokes.map { stroke in stroke.reduce(0) { $0 + length(of: $1) } }

    /// Pen travel in the same units, including a pause (as distance) between strokes while the pen is lifted.
    static let liftDistance: CGFloat = 160
    static let totalDistance: CGFloat = strokeLengths.reduce(0, +) + liftDistance * CGFloat(max(strokes.count - 1, 0))

    private static func length(of s: Segment) -> CGFloat {
        var total: CGFloat = 0
        var previous = s.start
        for i in 1...12 {
            let t = CGFloat(i) / 12, u = 1 - t
            let point = CGPoint(
                x: u * u * u * s.start.x + 3 * u * u * t * s.control1.x + 3 * u * t * t * s.control2.x + t * t * t * s.end.x,
                y: u * u * u * s.start.y + 3 * u * u * t * s.control1.y + 3 * u * t * t * s.control2.y + t * t * t * s.end.y)
            total += hypot(point.x - previous.x, point.y - previous.y)
            previous = point
        }
        return total
    }
